using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool, Description("Fetches a post by ID from an external API.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to retrieve.")] int id)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"/posts/{id}");
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public sealed class SummarizePrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks for a concise summary of the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text)
    {
        return
        [
            new()
            {
                Role = Role.User,
                Content = new Content { Type = "text", Text = $"Please provide a concise summary of the following text:\n\n{text}" }
            }
        ];
    }
}

